/* ── Configuración editable ──────────────────────────────────────
   VALOR_HORA es el único número de negocio que vive en n8n. Las horas
   de cada módulo viven en Notion y se editan allá, no acá.          */
const VALOR_HORA = 45000;

/* id que manda la web  →  valor exacto de la columna "Servicio" en Notion.
   Para sumar un servicio nuevo: agregá la fila acá y en la web.       */
const SERVICIOS = {
  'web-comercial':    'Web comercial',
  'automatizaciones': 'Automatizaciones',
  'dashboards':       'Dashboards y herramientas internas',
  'ia-aplicada':      'IA aplicada'
};

const MAX_CANTIDAD = 20;   // techo por módulo, para que nadie pida 9999

function txt(p) {
  if (!p) return '';
  const arr = p.title || p.rich_text;
  return Array.isArray(arr) ? arr.map(t => t.plain_text).join('') : '';
}
const sel = (p) => (p && p.select ? p.select.name : '');
const num = (p) => (p && typeof p.number === 'number' ? p.number : 0);
const chk = (p) => !!(p && p.checkbox);

/* Convierte las filas crudas de Notion en los módulos de un servicio. */
function modulosDe(results, servicioNombre) {
  return (results || [])
    .map((r) => {
      const p = r.properties || {};
      return {
        id:          String(r.id).replace(/-/g, ''),
        nombre:      txt(p['Módulo']),
        descripcion: txt(p['Descripción']),
        pregunta:    txt(p['Pregunta del formulario']),
        categoria:   sel(p['Categoría']),
        servicio:    sel(p['Servicio']),
        seAplica:    sel(p['Se aplica']),
        horas:       num(p['Horas']),
        activo:      chk(p['Activo'])
      };
    })
    .filter((m) => m.activo && m.servicio === servicioNombre && m.horas > 0)
    /* Las preguntas entre paréntesis no se le muestran al cliente:
         · Base  → se incluye siempre, no se pregunta
         · resto → no se cotiza desde la web (ej. "Ronda de revisión extra") */
    .filter((m) => m.categoria === 'Base' || !/^\s*\(/.test(m.pregunta))
    .map((m) => Object.assign({}, m, {
      control: m.categoria === 'Base'
        ? 'incluido'
        : (m.seAplica === 'Una vez' ? 'toggle' : 'cantidad')
    }))
    .sort((a, b) => {
      if (a.categoria === 'Base') return -1;
      if (b.categoria === 'Base') return 1;
      return a.nombre.localeCompare(b.nombre, 'es');
    });
}

/* Resuelve el precio. NUNCA confía en lo que manda el navegador:
     · los módulos Base entran siempre en 1
     · las cantidades se recortan a [0, MAX_CANTIDAD]
     · los ids desconocidos se ignoran                                */
function cotizar(modulos, seleccion) {
  const desglose = [];
  let horas = 0;

  for (const m of modulos) {
    let cant;
    if (m.control === 'incluido') {
      cant = 1;
    } else {
      const pedido = Number((seleccion || {})[m.id]);
      cant = Number.isFinite(pedido) ? Math.floor(pedido) : 0;
      cant = Math.max(0, Math.min(MAX_CANTIDAD, cant));
      if (m.control === 'toggle') cant = cant > 0 ? 1 : 0;
    }
    if (cant === 0) continue;

    const h = m.horas * cant;
    horas += h;
    desglose.push({
      id: m.id,
      modulo: m.nombre,
      descripcion: m.descripcion,
      categoria: m.categoria,
      cantidad: cant,
      horas: h,
      subtotal: h * VALOR_HORA
    });
  }

  return { horas: horas, valor_hora: VALOR_HORA, total: horas * VALOR_HORA, desglose: desglose };
}

/* ══ Devuelve los módulos de un servicio SIN horas ni precios ══════
   Es lo que dibuja el formulario de la web. Si acá mandáramos las
   horas, la tabla de precios quedaría a la vista en el navegador.  */
const q = $('Webhook módulos').first().json.query || {};
const servicioId = String(q.servicio || '');
const servicioNombre = SERVICIOS[servicioId];

if (!servicioNombre) {
  return [{ json: { error: 'servicio desconocido', modulos: [] } }];
}

const modulos = modulosDe($input.first().json.results, servicioNombre);

return [{
  json: {
    servicio: { id: servicioId, nombre: servicioNombre },
    modulos: modulos.map((m) => ({
      id: m.id,
      nombre: m.nombre,
      descripcion: m.descripcion,
      pregunta: m.pregunta,
      categoria: m.categoria,
      control: m.control,
      max: m.control === 'cantidad' ? 10 : undefined
    }))
  }
}];

